const IP_DATA_B64 = "";

let geoCCList = [];
let geoStarts = null;
let geoEnds = null;
let geoCCIdx = null;
let geoEngineReady = false;

function isIPv4(ip) {
    if (!ip) return false;
    const parts = String(ip).trim().split(".");
    if (parts.length !== 4) return false;
    return parts.every(part => {
        if (!/^\d+$/.test(part)) return false;
        const n = Number(part);
        return n >= 0 && n <= 255;
    });
}

function isPrivateIPv4(ip) {
    if (!isIPv4(ip)) return false;
    const [a, b] = String(ip).trim().split(".").map(Number);
    return (
        a === 10 ||
        a === 127 ||
        (a === 169 && b === 254) ||
        (a === 172 && b >= 16 && b <= 31) ||
        (a === 192 && b === 168) ||
        a === 0
    );
}

function ipv4ToInt(ip) {
    const parts = String(ip).trim().split(".").map(Number);
    return ((parts[0] << 24) >>> 0) + (parts[1] << 16) + (parts[2] << 8) + parts[3];
}

const CITY_DATA_B64 = "";
let subnetCityMap = {};

function initCityEngine() {
    try {
        const rawStr = atob(CITY_DATA_B64);
        const bytes = new Uint8Array(rawStr.length);
        for (let i = 0; i < rawStr.length; i++) {
            bytes[i] = rawStr.charCodeAt(i);
        }
        if (typeof pako !== "undefined" && pako.inflate) {
            const decompressed = pako.inflate(bytes, { to: 'string' });
            subnetCityMap = JSON.parse(decompressed);
        }
    } catch (e) {
        console.error("City engine init error:", e);
    }
}

function lookupCityByIp(ip) {
    if (!ip || !isIPv4(ip) || isPrivateIPv4(ip)) return "";
    const parts = String(ip).trim().split(".");
    if (parts.length < 3) return "";
    const subnet = parts.slice(0, 3).join(".");
    return subnetCityMap[subnet] || "";
}

function initIpGeoEngine() {
    initCityEngine();
    if (geoEngineReady) return;
    try {
        const rawStr = atob(IP_DATA_B64);
        const compBytes = new Uint8Array(rawStr.length);
        for (let i = 0; i < rawStr.length; i++) {
            compBytes[i] = rawStr.charCodeAt(i);
        }

        let decompressed;
        if (typeof pako !== "undefined" && pako.inflate) {
            decompressed = pako.inflate(compBytes);
        } else {
            console.error("pako zlib library not loaded");
            return;
        }

        let pos = 0;
        const numCCs = decompressed[pos++];
        geoCCList = [];
        for (let i = 0; i < numCCs; i++) {
            const cc = String.fromCharCode(decompressed[pos], decompressed[pos + 1]);
            pos += 2;
            geoCCList.push(cc);
        }

        const startsArr = [];
        const endsArr = [];
        const ccIdxArr = [];

        let curE = 0;
        const len = decompressed.length;
        while (pos < len) {
            let sDelta = 0;
            let shift = 0;
            while (true) {
                const b = decompressed[pos++];
                sDelta |= (b & 0x7f) << shift;
                if (!(b & 0x80)) break;
                shift += 7;
            }

            let span = 0;
            shift = 0;
            while (true) {
                const b = decompressed[pos++];
                span |= (b & 0x7f) << shift;
                if (!(b & 0x80)) break;
                shift += 7;
            }

            const ccIdx = decompressed[pos++];

            const sIp = curE + sDelta;
            const eIp = sIp + span;
            curE = eIp;

            startsArr.push(sIp);
            endsArr.push(eIp);
            ccIdxArr.push(ccIdx);
        }

        geoStarts = new Float64Array(startsArr);
        geoEnds = new Float64Array(endsArr);
        geoCCIdx = new Uint8Array(ccIdxArr);
        geoEngineReady = true;
    } catch (e) {
        console.error("Failed to initialize IP Geolocation Engine:", e);
    }
}

function lookupCountryCodeByIp(ip) {
    if (!geoEngineReady || !isIPv4(ip) || isPrivateIPv4(ip)) return "";
    const ipNum = ipv4ToInt(ip);

    let low = 0;
    let high = geoStarts.length - 1;
    while (low <= high) {
        const mid = (low + high) >> 1;
        const s = geoStarts[mid];
        const e = geoEnds[mid];
        if (ipNum >= s && ipNum <= e) {
            return geoCCList[geoCCIdx[mid]] || "";
        } else if (ipNum < s) {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return "";
}

function isIPv6(value) {
    const ip = String(value || "").trim();
    if (!ip || !ip.includes(":")) return false;

    // Accept normal IPv6 notation, including compressed forms (::).
    const parts = ip.split("::");
    if (parts.length > 2) return false;

    const left = parts[0] ? parts[0].split(":") : [];
    const right = parts.length === 2 && parts[1] ? parts[1].split(":") : [];

    const valid = part => /^[0-9a-fA-F]{1,4}$/.test(part);

    if (!left.every(valid) || !right.every(valid)) return false;

    const count = left.length + right.length;
    return parts.length === 2 ? count < 8 : count === 8;
}

function getPublicServerIp(server) {
    const candidates = [
        server?.resolved_external_ip_address,
        server?.external_ip,
        server?.public_ip,
        server?.publicIp,
        server?.ip,
        server?.address ? String(server.address).trim() : ""
    ];

    for (const raw of candidates) {
        const ip = String(raw || "").trim();
        if (isIPv4(ip) && !isPrivateIPv4(ip)) return ip;
        if (isIPv6(ip)) return ip;
    }

    return "";
}

